/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/eo.json — nu edita de mână */
__hubApps("eo",{"FreeDetect":{"line":"Ĉu vi volas kontroli, ĉu teksto ŝajnas verkita de AI aŭ kopiita? Jen 42 eksteraj iloj kaj citaĵa generilo en unu loko. La aplikaĵo mem nenion detektas.","detail":"Panelo de 42 eksteraj iloj por detekti AI/plagiaton kaj citaĵa generilo (validigas ISBN). Ĝi nenion detektas loke; ĝi helpas kontroli referencojn.","tags":["katalogo","citaĵoj"]},"Arhiva-fara-frontiere":{"line":"Foliumu la kolektojn de Internet Archive sen konto: serĉu, rigardu paĝojn de eroj, antaŭrigardu kaj konservu viajn plej ŝatatajn. Neoficiala; archive.org vidas vian IP kaj serĉojn.","detail":"Neoficiala foliumilo por la kolektoj de Internet Archive (serĉo, paĝoj de eroj, antaŭrigardo, ŝatataĵoj kaj lastaj serĉoj konservitaj loke), sen konto. Ĝi ne serĉas en Wayback Machine; archive.org ricevas vian IP kaj serĉojn.","tags":["retaj arkivoj","fontoj"]},"AcademiSearch":{"line":"Serĉu unufoje kaj vidu sciencajn artikolojn el dekoj da malfermitaj fontoj. Vi povas konservi la liston por citaĵoj. Bezonas interreton; viaj serĉoj iras al tiuj servoj.","detail":"Akademia metaserĉo tra 11 malfermitaj API-oj (OpenAlex, Crossref, arXiv ktp.) plus ligiloj al portaloj; eksporto BibTeX/RIS/CSV. Postulas interreton; viaj demandoj iras al tiuj servoj.","tags":["literaturo","fontoj"]},"Surveyor":{"line":"Kiujn ligilojn havas via retejo, kaj kiuj estas rompitaj? Ĝi listigas ilin, kun ankroj kaj alidirektoj. Eksteraj ne povas esti fidinde konfirmitaj. Nur por viaj propraj retejoj.","detail":"Inventaras la ligilojn de retejo (senmova HTML, angla interfaco), inkluzive de ankroj kaj alidirektoj. Eksteraj ne povas esti konfirmitaj el la retumilo (CORS); ĝi sendas petojn; kontrolu nur viajn proprajn retejojn.","tags":["ligoputriĝo","kontrolo"]},"Trade-Free-Link-Guardian":{"line":"Por via WordPress-retejo: trovas rompitajn ligilojn kaj riparas ilin, sen ekstera servo. Ĝi ŝanĝas veran enhavon, do faru sekurkopion antaŭe. Ne testita en reala WordPress.","detail":"WordPress-kromaĵo, kiu kontrolas ligilojn kaj determinisme riparas rompitajn, sen ekstera servo. Ĝi modifas veran enhavon: faru sekurkopion. Netestita en reala WordPress.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Gardu viajn retejojn kaj vidu, ĉu ili ankoraŭ respondas. Funkcias nur dum la langeto restas malfermita. Erarpaĝo ankoraŭ validas kiel respondo. La interfaco estas en la angla.","detail":"Retumila monitoro de atingeblo: kontrolas ĉu viaj retejoj respondas (ne legas la HTTP-statuskodon; 404/500 validas kiel respondo). Nur dum la langeto estas malfermita. Angla interfaco.","tags":["monitorado"]},"ScryVeil":{"line":"Faru sekurecan kontrolon de domajno kaj ricevu tekstan raporton por konservi. Kelkaj kontroloj povas manki aŭ bezoni ŝlosilon. Ĝi kontaktas triajn servojn; nur propraj domajnoj.","detail":"Sekureca diagnozo de domajno (DNS, RDAP, atestiloj), kun eksportebla teksta raporto; kontroloj de kapoj kaj reputacio ofte estas blokitaj aŭ postulas ŝlosilon. Kontaktas triajn partiojn; nur por domajnoj, kiujn vi posedas.","tags":["OSINT","sekureco"]},"Vitrina":{"line":"Metu publikan Facebook-afiŝon en vian retejon, sen konto, kaj kopiu la pretan kodon por alglui. Neoficiala; Meta vidas vian IP, kaj montrado ne estas garantiita.","detail":"Enkonstruas publikajn Facebook-paĝojn/afiŝojn per Meta-kromaĵoj, neoficiale; kopias la enkonstruan kodon. “Sen konto” ne signifas “sen spurado”: Meta vidas vian IP; montrado ne estas garantiita.","tags":["monitorado de fontoj"]},"Threads-fara-cont":{"line":"Legu publikajn afiŝojn de Threads sen konto kaj konservu ilin kiel tekston. Neoficiala; Meta vidas vian IP, kaj foje necesas peranta servo.","detail":"Montras publikajn afiŝojn de Threads per la enkonstruo de Meta, sen konto; laŭvola loka konservado, eksporto .txt. Meta vidas vian IP; povas postuli CORS-prokuron. Neoficiala.","tags":["monitorado de fontoj"]},"X-fara-cont":{"line":"Atingu publikajn profilojn kaj afiŝojn en X sen konto, per pluraj manieroj: rekta ligilo, arkivo, serĉo aŭ Nitter. Ĝi ne legas la enhavon; ĝi sendas la ligilon al archive.org.","detail":"Generas senkontajn alirvojojn al publikaj profiloj kaj afiŝoj de X: rekta ligilo, arkivo Wayback, serĉo, Nitter. Ne legas la enhavon; sendas la uzantnomon/ligilon al archive.org.","tags":["monitorado de fontoj"]},"Arhiva-LinkedIn":{"line":"Tenu viajn notojn pri LinkedIn-afiŝoj, kiujn vi mem algluis, en unu loko kaj eksportu ilin kiel tekston. La galerio uzas la oficialan enkonstruon, do ĝi kontaktas LinkedIn. Neoficiala.","detail":"Arkivo de notoj pri permane algluitaj LinkedIn-afiŝoj (importo CSV, eksporto Markdown) + galerio per la oficiala LinkedIn-enkonstruo (kontaktas LinkedIn). Neoficiala.","tags":["arkivado"]},"Cadraj":{"line":"Kolektu TikTok-filmetojn permane, grupigitajn laŭ aŭtoro, kaj spektu ilin en la oficiala ludilo. Vi povas marki tion, kion vi jam vidis.","detail":"Mana kolekto de TikTok-filmetoj laŭ aŭtoro, ludataj per la oficiala ludilo; marko “vidite”.","tags":["monitorado de fontoj"]},"FASCICUL":{"line":"Igas la telefonojn en la ĉambro komuna tabulo sur videoprojektoro: desegnaĵoj, notoj, bildoj, lasera montrilo kaj viva kamerao. Testita en komputilo; ankoraŭ ne kontrolita en realaj telefonoj.","detail":"Telefonoj ↔ videoprojektoro: komuna tabulo kun desegnado, notoj, bildoj, lasera montrilo kaj viva kamerao, en unu dosiero. Rekta WebRTC-konekto en la loka reto, sen tria servilo; laŭvola relajso en la telefono-hotspoto (Android/Termux). Testita en Chromium; ankoraŭ ne kontrolita en realaj telefonoj.","tags":["kunlaboro"]},"INDICATIV":{"line":"Pretiĝu por la ekzameno de amatora radio de ANCOM per 723 demandoj, ripetataj je taŭgaj intervaloj, sen interreto. Neoficiala; la demandaro estas nur parte kontrolita.","detail":"Senreta, neoficiala trejnilo por la ekzameno de amatora radio de ANCOM (723 demandoj, interspaca ripetado, serĉo en la demandaro). Ne materialo de ANCOM; la demandaro estas nur parte kontrolita.","tags":["ekzameno","radio"]},"ETER":{"line":"Lernu amatoran radion en enciklopedio kun Morse-kodo, Morse-trejnilo, kalkuliloj de antenoj kaj serĉo tra la tuta enhavo.","detail":"Enciklopedio de amatora radio: Morse, trejnilo de Koch, kalkuliloj de antenoj, ĉea serĉo.","tags":["radio","enciklopedio"]},"ATINGERE":{"line":"Libro fariĝas brajlo sur la tuŝekrano, kun vibroj, por surdblinduloj, aŭ aŭdlibro por blinduloj. Ne validigita kun denaskaj legantoj; ĝi havas limojn.","detail":"Konvertas librojn en tuŝeblan brajlon aŭ aŭdlibrojn. Ne validigita kun denaskaj legantoj; vidu la limojn en la README.","tags":["alirebleco"]},"Clopotel":{"line":"Tenu vian konferencon aŭ laborrenkontiĝon ĝustatempe: scenejan tempomezurilon kun via tagordo kaj signalo, kiu avertas kiam la fino proksimiĝas. Rumane kaj angle.","detail":"Scenejo-tempomezurilo kun tagordo de parolantoj (importo teksto/CSV) kaj averta signalo, RO/EN.","tags":["eventoj","MIT"]},"Monstrarium":{"line":"Planu laborrenkontiĝon pri farado de monstroj el recikligitaj materialoj: la aplikaĵo kalkulas materialojn kaj sesiojn kaj proponas 50 monstrojn kun sonoj, 3D kaj eduka ludo.","detail":"Planilo por laborrenkontiĝo de monstroj el recikligitaj materialoj: mem kalkulas la materialojn, horaro laŭ serioj, 50 originalaj monstroj kun sonoj, 3D kaj eduka ludo.","tags":["laborrenkontiĝo","MIT"]},"TranslateHub":{"line":"Elektu inter 22 tradukiloj aŭ tradukiĝu per AI per via propra ŝlosilo. Teksto tradukita per AI iras al la servo de Anthropic.","detail":"Dosierujo de 22 tradukiloj plus AI-tradukilo per via propra ŝlosilo. AI-teksto estas sendata al api.anthropic.com.","tags":["tradukado","AI"]},"DataWeave":{"line":"Malfermu tabelon kaj komprenu ĝin: statistiko, diagramoj, pivotaj tabeloj kaj korelacioj. Viaj datumoj restas en via aparato.","detail":"Esploru CSV/TSV/JSON en unu dosiero: tabelo, statistiko, diagramoj, pivoto kaj korelacioj; viaj datumoj restas en via aparato.","tags":["datumoj"]},"MarkdownAtelier":{"line":"Skribu dokumentojn en Markdown kaj tuj vidu kiel ili aspektas, kun simplaj formuloj, en 7 lingvoj, sen interreto. Tekstoj restas en via retumilo; konservu sekurkopion.","detail":"Senreta Markdown-redaktilo kun antaŭrigardo, GFM, subaro de LaTeX (MathML), 7 lingvoj, serĉo kaj sekurkopio .json. Dokumentoj restas en la retumilo.","tags":["verkado"]},"RegexLab":{"line":"Provu regulan esprimon kaj vidu tuj, kion ĝi kongruas, kun paŝo-post-paŝaj klarigoj, testoj kaj averto kiam ĝi povus frostigi la programon.","detail":"Testado de JavaScript-regulaj esprimoj kun klarigoj, testoj kaj ReDoS-alarmo.","tags":["programado"]},"SEOptimum":{"line":"Kontrolu kiom bone retpaĝo estas preparita por serĉiloj. Ĝi havas 20 ilojn, inkluzive de paĝa analizo kaj antaŭrigardo de ĝia aspekto en serĉrezultoj.","detail":"20 retumilaj SEO-iloj: surpaĝa analizo, antaŭrigardoj de SERP.","tags":["reto"]},"SEVA":{"line":"Lernu pli pri dormo, ĉiutaga ritmo de la korpo, spirado kaj nutrado, en enciklopedio, kiun vi ankaŭ povas aŭskulti. Nur informe; ne kuracista konsilo.","detail":"Enciklopedio pri bonfarto: dormo, cirkada ritmo, spirado, nutrado; voĉlegado. Informa; ne kuracista konsilo.","tags":["sano"]},"PULS":{"line":"Kion fari ĝis alvenos la ambulanco? Gvidilo pri unua helpo en la rumana, kun RCP-metronomo kaj laŭvola urĝa karto. Ne klinike validigita; telefonu 112.","detail":"Gvidilo pri unua helpo en la rumana (RCP kun metronomo, tornikedo), kun serĉo kaj laŭvola urĝa karto. Enhavo ne klinike validigita de fakulo; ne anstataŭas rajtigitan kurson. En urĝo, telefonu 112.","tags":["sano","urĝo"]},"VATRA":{"line":"Kion fari se vi restas sen akvo, fajro aŭ ŝirmejo en la sovaĝejo? Postvivenciklopedio, sen interreto, kun serĉo kaj notoj. Nur eduke; en urĝo telefonu 112.","detail":"Senreta enciklopedio de postvivo (akvo, fajro, ŝirmejo, navigado), kun serĉo kaj notoj konservitaj loke. Eduka materialo, ne anstataŭas kurson pri unua helpo; en urĝo telefonu 112.","tags":["kampa laboro"]},"Eclipsa-2027":{"line":"Vidu sur mapo kie kaj kiom longe daŭras la tuta suneklipso de la 2-a de aŭgusto 2027, kun urboj kaj serĉo de lokoj, sen interreto. Proksimumaj valoroj; ne rigardu la Sunon sen filtriloj.","detail":"Senreta mapo de la tuta eklipso de la 2-a de aŭgusto 2027, kun daŭroj, kovro laŭ urbo kaj serĉo de lokoj. Indikaj valoroj; ne rigardu la Sunon sen atestitaj filtriloj.","tags":["astronomio"]},"orarium":{"line":"Kioma horo estas nun sur Marso, sur la Luno aŭ sur asteroido? Vidu vivan lokan tempon sur 45 ĉielaj korpoj. Proksimuma modelo, sen interreto; ne por navigado.","detail":"Tempo sur ĉiu mondo: viva loka tempo sur 45 korpoj (Luno, Marso, planedoj, lunoj, asteroidoj), horloĝa rapido kompare al la Tero, distanco kaj tempo de irvojaĝo, konvertilo de horzonoj kaj kolonizaj mapoj. Indika modelo, senrete; ne por navigado. Inkluzivas noktomezon kaj tagmezon sur ĉiu korpo, transmetajn fenestrojn Tero–korpo kaj ligilon al TerRa.","tags":["astronomio","tempo"]},"TerRa":{"line":"3D-globo kaj mapo montrantaj tagon kaj nokton sur la Tero, la Luno kaj la planedoj. Pozicioj de satelitoj povas esti ĉirkaŭ 3 monatojn malnovaj ĝis vi ĝisdatigos rete.","detail":"3D-globo kaj mapo: terminatoro, Luno, planedoj. Satelitoj uzas malaktualan momentfoton (~3 monatoj) senrete; por nunaj pozicioj, ĝisdatigu rete. Unika ligilo por ĉiu vido; la ĉielo de iu ajn el la 45 korpoj de ORARIUM, ligita ambaŭdirekte.","tags":["astronomio"]},"Horizons.BeyondLimits":{"line":"Vojaĝu tra la historio de la universo de la Praeksplodo ĝis la fino, en 91 gravaj eventoj. La estonteco estas scienca konjekto, ne certa prognozo.","detail":"Tempolinia mapo de la Praeksplodo ĝis la fino de la universo: 91 eventoj, eksporto Markdown; la estonteco estas konjekta, ne validigita prognozo.","tags":["kosmologio"]},"Hyper4D":{"line":"Vidu kiel aspektas kvar-dimensiaj formoj: turnu ilin sur la ekrano kaj rigardu ilin el pluraj anguloj. Bildoj povas esti konservitaj.","detail":"4D-geometrio en SVG: 3D-sekcoj de 4D-korpoj kaj politopoj kun projekcioj 4D→3D→2D turnataj en reala tempo, eksporto SVG.","tags":["matematiko"]},"ExploratoriiEco":{"line":"Kampa gvidilo por naturamantoj: de la klasifiko de vivaĵoj kaj iliaj spuroj ĝis la biomoj de Rumanio, taglibro, etiko kaj urĝoj.","detail":"Kampa gvidilo por naturistoj en 20 sekcioj: klasifiko de vivo, signoj kaj spuroj, rumaniaj biomoj, kalkuliloj, taglibro, etiko, urĝoj kaj glosaro.","tags":["naturo"]},"FieldObserver":{"line":"Notu viajn kampajn observojn, kaj la telefono aŭtomate aldonas mezurojn de siaj sensiloj. Vi tenas arkivon de viaj elirejoj.","detail":"Taglibro de kampaj observoj per la sensiloj de la telefono; arkivo, eksporto JSON/CSV.","tags":["kampa laboro"]},"VietAR":{"line":"Fotu aŭ registru planton aŭ estaĵon kaj ricevu ideon pri la specio, el 519 de Rumanio. Ĝi povas erari; ne manĝu ion surbaze de ĝi.","detail":"Indika identigo de 519 rumaniaj specioj el bildo/sono; ĝi povas erari, ne manĝu plantojn aŭ fungojn surbaze de ĝi. Modeloj estas elŝutataj de triaj partioj; ne tute senrete.","tags":["biodiverseco"]},"VOIAJOR":{"line":"Sekvu la trajektoriojn de Voyager 1 kaj 2 de 1977 ĝis miliardo da jaroj antaŭen, laŭ ajna skalo, de la planedoj ĝis la Lakta Vojo. Indika modelo, ne navigado.","detail":"Simulado de la trajektorioj de Voyager 1 kaj 2 (1977 ĝis pli ol miliardo da jaroj): balistikaj arkoj inter la realaj preterfluoj, ekstrapolo kun suna gravito kaj loka galaksia dinamiko, la heliosfero, la nubo de Oort kaj 19 proksimaj steloj kun propra movo.","tags":["Voyager","simulado"]},"Nemurirea":{"line":"Eksciu kiel la korpo maljuniĝas kaj kion scienco diras pri biologiaj horloĝoj kaj longviveco, poste testu vin per kvizo. Ne kuracista konsilo.","detail":"Interaga eseo pri biologiaj horloĝoj kaj la scienco de longviveco, kun fina kvizo. Informa celo, ne kuracista konsilo.","tags":["biologio"]},"IncredibleCosmos":{"line":"Metu planedojn kaj stelojn tiel, ke ilia gravito gvidu kometon al la celo. 108 niveloj, tri malfacilecoj kaj ĝis tri steloj por nivelo.","detail":"Gravita puzlo: metu planedojn kaj stelojn tiel, ke ilia gravito gvidu kometon al la celo; 108 niveloj en 12 kategorioj, tri malfacilecoj, takso de 1–3 steloj, kun serĉo.","tags":["ludo","fiziko"]},"Cupa-Mondiala-2026":{"line":"Ludu ĉe la Mondpokalo 2026 kaj spektu imagan turniron. Rezultoj estas hazardaj, ne prognozoj; neoficiala.","detail":"Fikcia, neoficiala simulilo de la Mondpokalo 2026: hazardaj rezultoj, ne prognozoj; ne rilata al FIFA.","tags":["simulado","neoficiala"]},"AGORA":{"line":"Kiel naskiĝis la eŭro kaj kion ĝi signifas por Rumanio? 59 sekcioj, de Maastricht ĝis la ECB, plus konsiloj por vojaĝantoj. Neoficiala.","detail":"Informa atlaso de la eŭrozono en 59 sekcioj: de Maastricht kaj la ECB ĝis Rumanio kaj la eŭro, plus gvidilo por vojaĝantoj. Neoficiala, sen jura valoro.","tags":["ekonomio","EU"]},"URME":{"line":"Pretiĝu por migrado sur la vojo Colți–Aluniș en Buzău: plantoj, sukceno, fosilioj, tempoj de sunleviĝo kaj sunsubiro, ekipaĵo. La mapo ne estas por navigado.","detail":"Informa, neoficiala migrogvidilo por Colți–Aluniș (plantoj, sukceno, fosilioj), kun sunleviĝo/sunsubiro kaj ekipaĵlisto. Skema mapo, ne por navigado; ĉerpado el la protektata areo estas malpermesita.","tags":["naturo","Buzău"]},"Belot-fara-frontiere":{"line":"Eksciu pri belote kaj ĝiaj parencoj el aliaj landoj, poste ludu ĉe la tablo: vi kaj AI-kunludanto kontraŭ du AI-kontraŭuloj. Inkluzivas poentofolion.","detail":"Atlaso de la familio belote/bela/klaverjas/jass kaj ludo por 4 ludantoj (vi kaj AI-kunludanto kontraŭ du AI-kontraŭuloj); rumana belot estas prioritata; poentofolio.","tags":["kartoj","AI"]},"Scopone-fara-frontiere":{"line":"Eksciu kiel naskiĝis Scopone, kiaj estas ĝiaj reguloj kaj kiel ili malsamas de regiono al regiono, poste ludu kontraŭ la komputilo, kiu povas doni al vi sugestojn.","detail":"Atlaso de Scopone (15 folioj: deveno, reguloj, regionaj diferencoj) kaj ludo kontraŭ loka AI (heŭristika / Monte-Carlo), kun sugestoj; italaj aŭ francaj koloroj.","tags":["kartoj","AI"]},"Solitaire-fara-frontiere":{"line":"Foliumu ludojn de pasjanco kiel Klondike, FreeCell aŭ Spider kaj ludu ilin. Kiam vi blokiĝas, petu sugeston aŭ lasu la komputilon solvi.","detail":"Atlaso de pasjancaj ludoj (Klondike, FreeCell, Spider kaj aliaj) sur komuna motoro; “Sugesto” de solvilo kun limo de nodoj/tempo kaj laŭvola aŭtosolvo.","tags":["kartoj"]},"Sudoku-fara-frontiere":{"line":"136 specoj de Sudoku, de klasika ĝis killer aŭ 3D, por foliumi kaj ludi. Ĝi helpas per paŝo-post-paŝaj klarigoj kaj solvas viajn proprajn puzlojn.","detail":"Atlaso de 136 Sudoku-variantoj (klasika, killer, jigsaw, greklatina, 3D kaj multaj aliaj), kun generilo de unika solvo, klarigita paŝo-post-paŝa solvado, 7 ludreĝimoj kaj solvilo.","tags":["puzlo"]},"Domino-fara-frontiere":{"line":"Lernu la historion kaj regulojn de domino, poste ludu ĉe la tablo kontraŭ unu ĝis tri komputilaj kontraŭuloj. Vi povas malfari movon.","detail":"Atlaso de domino (deveno, reguloj, proksimumaĵoj) kaj ludtablo kontraŭ 1–3 AI-ludantoj, kun tri niveloj; malfari movon.","tags":["domino","AI"]},"Mahjong-fara-frontiere":{"line":"Eksciu pri 8 variantoj de mahjong kaj ludu pasjancon aŭ la kvarpersonan ludon, kun tri simplaj komputilaj kontraŭuloj. Funkcias senrete.","detail":"Atlaso de 8 mahjong-variantoj, pasjanco kaj mahjong por 4 ludantoj (riichi, Hongkongo, Siĉuano) kontraŭ 3 simplaj heŭristikaj AI. Senrete.","tags":["Mahjong","AI"]},"Go-fara-frontiere":{"line":"Eksciu de kie venas Go kaj kiel oni ludas ĝin, poste provu vin kontraŭ la komputilo, kiu povas doni sugestojn. Ĝi sendas neniujn datumojn tra interreto.","detail":"Atlaso de Go (18 folioj: deveno, reguloj, proksimumaĵoj) kaj ludo kontraŭ loka AI (Monte-Carlo, ne LLM), kun SGF kaj sugestoj; neniuj retaj petoj.","tags":["Go","AI"]},"Zaruri-fara-frontiere":{"line":"26 ludkubaj ludoj por legi, 12 el ili ludeblaj kontraŭ la komputilo, plus ĵetosimulilo kun probabloj. Neniu mono implikita; senrete.","detail":"Atlaso de 26 ludkubaj ludoj; 12 ludeblaj kontraŭ didaktika AI (ne LLM), plus simulilo NdM kun precizaj probabloj. Ne hazardludo; senrete.","tags":["ludkuboj"]},"Sah-fara-frontiere":{"line":"Pli ol 700 ŝakaj variantoj por esplori, kun malgranda vortaro de terminoj; por multaj vi povas ludi kontraŭ la komputilo. Funkcias senrete.","detail":"706 ŝakvariantaj enskriboj (nur kelkaj kun kontrolita fonto; kelkaj sintezaj) kaj 299 leksikaj terminoj. Senrete, kun loka motoro por multaj variantoj.","tags":["ŝako"]},"Dame-fara-frontiere":{"line":"Ludu 25 variantojn de damludo kontraŭ la komputilo kaj konservu vian ludon. La reguloj de 16 el ili estas nur proksimumaj, markitaj per ⚠.","detail":"25 variantoj de damludo ludeblaj kontraŭ didaktika AI, kun eksporto de ludo; 16 havas proksimumajn regulojn (markitaj per ⚠).","tags":["damludo"]},"Table-fara-frontiere":{"line":"Triktrako, Tavli, Narde kaj la rumanaj variantoj de tabla, por legi kaj ludi: 17 variantoj kontraŭ la komputilo, per klavaro aŭ muso.","detail":"Ludebla atlaso de la triktraka familio: triktrako, Tavli, Tavla, Narde, Gul Bara kaj rumanaj variantoj; 17 variantoj kontraŭ instrua AI; ludo per klavaro.","tags":["triktrako"]},"Remi-fara-frontiere":{"line":"Eksciu pri la remia familio kaj ludu 19 variantojn kontraŭ la komputilo, kun statistiko. Ĝi havas 8 lingvojn kaj grandajn, facile videblajn pecojn aŭ kartojn.","detail":"Atlaso de la familio de remiaj ludoj: 19 ludeblaj variantoj kontraŭ loka AI, kun statistiko; interfaco en 8 lingvoj, kun grandaj pecoj kaj kartoj.","tags":["remio"]},"Carti-de-joc-fara-frontiere":{"line":"De Pasjanco kaj Nigra Petro ĝis pokero: 17 kartludoj kun klarigitaj reguloj, 8 el kiuj vi ankaŭ povas tuj ludi.","detail":"Interaga atlaso de kartludoj, de Pasjanco kaj Nigra Petro ĝis pokero: 17 ludoj kun regulfolioj, 8 el ili ludeblaj.","tags":["kartoj"]},"Undava":{"line":"Faru aŭ ludu kvizon kun amikoj, en la sama telefono aŭ komputilo, kaj replu la demandojn, kiujn vi malĝuste respondis. Simila al Kahoot, sed sendependa.","detail":"Kvizo laŭ Kahoot (sendependa), en unu dosiero: sola aŭ pasigi-kaj-ludi en la sama aparato, kun repludo de eraroj. Viva ludo estas nur en la servila eldono.","tags":["kvizo","edukado"]},"AI-Liber":{"line":"Parolu kun pluraj AI-helpantoj el unu loko, inkluzive de kelkaj, kiuj funkcias en via propra komputilo. Mesaĝoj iras al la provizanto, kiun vi elektas; AI povas erari.","detail":"Babilo kun pluraj AI-provizantoj, inkluzive de lokaj (Ollama, WebLLM). Mesaĝoj iras al la provizanto, kiun vi elektas; AI-respondoj povas esti malĝustaj.","tags":["AI"]},"LocalMind":{"line":"Babilu kun malgranda AI-helpanto, kiu funkcias rekte en via retumilo. Modeloj estas elŝutataj de interreto unufoje; ĝi povas erari.","detail":"Babilo kun malgrandaj modeloj (Qwen3, LFM2) lokaj en la retumilo (WebGPU). Modeloj venas de Hugging Face; ĝi povas erari. Postulas lokan servilon aŭ la publikan paĝon.","tags":["loka AI"]},"PromptVault":{"line":"Pli ol 500 pretaj promptoj por AI-helpantoj, el kiuj vi elektas kaj markas viajn ŝatatajn. Ĝi ne konservas viajn proprajn tekstojn.","detail":"Biblioteko de 500+ promptoj kun ŝatataĵoj, ne mastrumilo de viaj propraj promptoj.","tags":["promptoj"]},"ARENA":{"line":"Lasu du AI-modelojn respondi blinde kaj voĉdonu por la plej bona; la rangotabelo restas en via komputilo. Vi bezonas viajn proprajn ŝlosilojn.","detail":"Blindaj duelaj matĉoj inter AI-modeloj kun loka rangotabelo Elo (eksporto CSV). Postulas viajn proprajn API-ŝlosilojn aŭ lokajn servilojn; la demonstraj modeloj estas simulitaj.","tags":["AI-takso"]},"Nexus-fara-frontiere":{"line":"Babilu kun AI-helpantoj de pluraj provizantoj, kun serĉo en konversacioj kaj konservado. Vi bezonas interreton kaj viajn proprajn ŝlosilojn, kiuj estas konservitaj neĉifrite.","detail":"AI-babila kliento per viaj propraj API-ŝlosiloj (Anthropic, OpenAI, Google, OpenAI-kongruaj), kun serĉo kaj eksporto Markdown; la “agentoj” estas promptoj. Postulas interreton; ŝlosiloj estas konservitaj neĉifrite.","tags":["agentoj"]},"VoiceAtelier":{"line":"Aŭdu kiel sonas centoj da artefaritaj voĉoj en dekoj da lingvoj kaj lernu kiel oni faras aŭdlibron. La reta specimeno sendas la tekston al eksteraj servoj, nur kun via konsento.","detail":"Katalogo de 427 neŭralaj voĉoj (141 lokaĵaroj) kaj gvidilo pri aŭdlibroj. La reta specimeno sendas la tekston al relajso kaj al Microsoft, nur kun via konsento. Ne TTS-studio.","tags":["voĉo"]},"Trusa-fara-frontiere":{"line":"Ilaro de 15 malgrandaj ĉiutagaj iloj: notoj, kalkultabelo, Markdown, pasvortoj, financa taglibro kaj pli. Ĝi ne havas oficialan ligon kun YunoHost, kiu inspiris ĝiajn kategoriojn.","detail":"Aro de 15 malgrandaj moduloj skribitaj de nulo (notoj, kalkultabelo, Markdown, pasvortoj, financa taglibro kaj pli), inspiritaj de aplikaĵaj kategorioj de YunoHost; ne rilata.","tags":["utilaĵoj"]},"API-fara-frontiere":{"line":"Vidu veteron, bildojn de NASA, la pozicion de ISS kaj dekojn da aliaj vivaj detaloj en unu loko. Ĝi bezonas interreton kaj ne estis testita kun la realaj servoj.","detail":"52 fenestraĵoj: 47 super publikaj API-oj (bezonas interreton; malfermite rete ĝi aŭtomate kontaktas Open-Meteo, NASA kaj ISS) kaj 5 lokaj utilaĵoj. Netestita kontraŭ realaj serviloj.","tags":["API"]},"OmniHost":{"line":"Granda pako de pli ol cent laboriloj kolektitaj en unu loko. Ĝi kontaktas kvar eksterajn servojn; detaloj estas en la README.","detail":"Produktiveca ilaro (~4 MB, 141 moduloj). Kontaktas kvar eksterajn gastigantojn; vidu la README.","tags":["ilaro"]},"VNTV":{"line":"Lasu antaŭfilmojn de VideoNeat ludiĝi kiel televida kanalo, kiu neniam ĉesas. Bezonas interreton; en P2P-reĝimo via adreso estas videbla al aliaj spektantoj.","detail":"Antaŭfilmoj de VideoNeat kiel daŭra televida programo, plus Stremio-kromaĵo. Postulas interreton (videoneat.com, videos.trom.tf); en P2P-reĝimo via IP estas videbla al aliaj spektantoj.","tags":["amaskomunikiloj","MIT"]},"OSATURA":{"line":"Vivigu 2D-desegnaĵojn: muntu ilin sur “skeleto”, movu ilin kaj eksportu la animacion en pluraj formatoj. Alfa-versio, ankoraŭ malmulte provita.","detail":"2D-vektora ĉenstaka kaj animada motoro en Rust (ostoj, IK, haŭtigo, fiziko, ŝtatmaŝinoj) kun retumila studio kaj eksporto al SVG, PNG, GIF, Lottie kaj glTF. Denaska programo (komandlinio + studio) kaj WebAssembly-modulo, ne unu HTML-dosiero; alfa, ankoraŭ malmulte provita de uzantoj. Permesiloj: bibliotekoj MPL-2.0, CLI AGPL-3.0-or-later.","tags":["animacio","MPL/AGPL"]},"OAZA":{"line":"Foliumu 340 senpagajn retajn servojn, kutime sen konto, kolektitajn en unu katalogo. La listo estis kontrolita en junio 2026, sed ne aŭtomate.","detail":"Katalogo de 340 senpagaj triapartiaj retaj servoj, kutime uzeblaj sen konto (ne aŭtomate kontrolitaj; kontrolitaj en junio 2026).","tags":["servoj"]},"VaultCrypt":{"line":"Ĉu vi havas ion por gardi for de scivolaj okuloj? Ŝlosu dosierojn kaj tekstojn per pasvorto, rekte en la retumilo. Perdita pasvorto ne povas esti rekuperita.","detail":"Ĉifrado AES-256-GCM de dosieroj kaj teksto en la retumilo. Ne sendepende kontrolita; perdita pasvorto ne povas esti rekuperita.","tags":["sekureco"]},"Akasha":{"line":"Kajero kun etikedoj, serĉo kaj ligoj inter paĝoj, kiu funkcias senrete. Por ne perdi ion, vi elŝutas freŝan kopion de la dosiero.","detail":"Senretaj notoj en unu dosiero, kun etikedoj, serĉo kaj ligoj [[Titolo]]; por konservi viajn datumojn vi elŝutas freŝan kopion de la dosiero (quine).","tags":["notoj"]},"CLEPSIDRA":{"line":"Retronombra horloĝo, alarmo kaj horaroj por labortagoj kaj semajnfinoj. Ĝi atentas feriojn kaj viajn proprajn eventojn.","detail":"Inversa horloĝo, alarmo, horaroj de labortago/semajnfino, ferioj, eventoj.","tags":["tempo"]},"Origami":{"line":"Lernu faldi paperon paŝo post paŝo: simboloj, teknikoj kaj ilustritaj modeloj. La aplikaĵo memoras kie vi haltis.","detail":"Gvidilo pri origamio: notacio, teknikoj, paŝo-post-paŝaj modeloj, kun progreso konservita loke.","tags":["arto"]},"Zicala":{"line":"Rumana proverbo ĉiutage, el kolekto de 550. Vi povas serĉi kaj konservi ŝatatajn; la komentoj estis skribitaj kun helpo de AI.","detail":"550 rumanaj proverboj kun proverbo de la tago, serĉo kaj eksporto/importo de ŝatataĵoj; la SWOT/TOWS-komentoj estas AI-helpataj.","tags":["kulturo"]},"Limpezimea":{"line":"Legu la sciencfikcian romanon “Limpezimea” en sep lingvoj. La akompana kroniko kaj kritika studo estis skribitaj kun helpo de AI (Claude).","detail":"La sciencfikcia romano “Limpezimea” en 7 lingvoj, leg-eldono. La kritika aparato (kroniko, studo) estis skribita kun helpo de AI (Claude).","tags":["literaturo"]},"Nota-Zero":{"line":"Spekulativa fikcia rakonto pri kordoteorio, en la rumana, angla kaj franca, kun notoj klarigantaj la sciencajn ideojn. Ĝi estas fikcio, ne akademia fonto.","detail":"Spekulativa fikcia rakonto pri kordoteorio, en la rumana, angla kaj franca, kun klarigaj sciencaj notoj (fikcio, ne akademia fonto).","tags":["literaturo"]},"Pendulul":{"line":"Planedo oscilas inter tri steloj kaj nigra truo: sciencfikcia romano en naŭ volumoj, verkita de Alexio kune kun Claude. Kun 3D-simulado, konservebla leganto por senreta legado, EPUB kaj PDF.","detail":"Naŭvolumena sciencfikcia romano de Alexio, verkita kun Claude: planedo oscilas inter tri steloj kaj nigra truo. Inkluzivas 3D-simuladon kaj la libroleganton en unu HTML-dosiero, kiun vi povas konservi kaj legi senrete, plus EPUB kaj PDF.","tags":["literaturo"]},"PrintreInteligente":{"line":"Eniru interagan sciencfikcian romanon, kun roluloj inspiritaj de la skipo de Artemis 2. La recenzoj estas fikciaj; tradukado, voĉo kaj AI-funkcioj uzas eksterajn servojn.","detail":"Interaga sciencfikcia romano, fikcio kun roluloj inspiritaj de la skipo de Artemis 2; la recenzoj estas fikciaj. Tradukado, reta voĉo kaj AI-funkcioj uzas eksterajn servojn.","tags":["literaturo"]},"BorderlessMelodies":{"line":"Aŭskultu muzikon, kiu mem komponiĝas, rekte en la retumilo. Vi povas eksporti ĝin kiel sonon, kaj ekzistas dormo-tempigilo.","detail":"Proceda muziko en Web Audio, kun sona eksporto kaj dormo-tempigilo.","tags":["muziko"]},"EcoulSpectral":{"line":"Vidu sonon kiel bildon, elektu la parton, kiu ĝenas vin, kaj izolu aŭ forigu ĝin. Inkluzivas bruoredukton, detekton de voĉo kaj konservon al WAV.","detail":"Loka spektrograma redaktilo: markas tempo–frekvencan regionon kaj izolas aŭ forigas ĝin; detekto de voĉo, bruoredukto, eksporto WAV.","tags":["sono"]},"Constelar":{"line":"Babilu kun virtualaj kunuloj, kiuj memoras viajn konversaciojn. Implicite ili respondas laŭ simplaj reguloj; vera AI nur se vi elektas provizanton, kaj viaj mesaĝoj iras al ĝi. Nur plenaĝuloj.","detail":"Konversaciaj kunuloj kun loka memoro. Implicite simpla regul-bazita motoro; vera AI nur se vi elektas provizanton (mesaĝoj estas senditaj al ĝi). Por plenaĝuloj; ne anstataŭas terapion.","tags":["AI"]},"Tarot":{"line":"Eksciu la historion de taroto, la simbolojn de la kartoj kaj kiel ili estas legataj, vidate kiel kultura fenomeno. Interaga kurso por sekvi laŭ via propra rapido.","detail":"Interaga kurso: la historio, simboloj kaj legado de la kartoj, kiel kultura fenomeno.","tags":["kulturo"]},"Numerologie":{"line":"Esploru numerologion kiel simbolan tradicion, en kvar niveloj kun ekzercoj, glosaro, taglibro kaj kalkulilo. Ĝi estas prezentita sen scienca validigo.","detail":"Interaga kurso pri numerologio kiel simbola tradicio: kvar niveloj, ekzercoj, glosaro, taglibro kaj kalkulilo; prezentita sen scienca validigo.","tags":["kulturo"]},"PUNCTUM":{"line":"Eduka atlaso de akupremo kaj punktaj terapioj: pli ol 400 punktoj sur interagaj mapoj, memzorgaj rutinoj kun gvidataj sesioj, pruvoj kaj sekureco. Ĝi ne anstataŭas kuraciston.","detail":"Eduka atlaso de punktaj terapioj (akupunkturo, akupremo, moksibustio, ventozado, orelterapio, refleksologio kaj pli): 410 punktoj sur 14 meridianoj, 60 variantoj kun nivelo de pruvoj, SVG-mapoj, malsanoj kaj rutinoj, kurso, kvizo, memorkartoj kaj personaj sekurecaj kontroloj.","tags":["sano","pruvoj"]},"Reiki":{"line":"Eksciu kio estas Reiki, spirita praktiko, kaj kion diras esplorado: oni trovis nesufiĉajn pruvojn pri ia efiko preter malstreĉiĝo. Ĝi ne anstataŭas kuraciston.","detail":"Kurso pri Reiki, spirita praktiko: recenzoj trovas nesufiĉajn pruvojn pri ia efiko preter malstreĉiĝo/placebo; ne anstataŭas kuraciston.","tags":["kulturo"]},"Bioenergoterapie":{"line":"Kurso klariganta kio estas bioenergia terapio kaj de kie ĝi venas. La praktiko ne havas sciencan pruvon de resanigo kaj ne anstataŭas kuraciston.","detail":"Kurso pri bioenergia terapio, praktiko sen scienca pruvo de resanigo; ne anstataŭas kuraciston.","tags":["kulturo"]},"CHIROMANTIA":{"line":"Interaga atlaso de manlegado: mapo de la manplato kun linioj, montetoj, fingroj kaj manspecoj, legita kiel kultura tradicio, kun sekcio pri scienco kaj kritika pensado. Sen scienca validigo.","detail":"Interaga atlaso de manlegado: SVG-mapo de la manplato (maldekstra/dekstra), linioj, montetoj, fingroj, manspecoj, fingrospuroj, mezuroj 2D:4D, gvidata legado, memorkartoj, kvizo, blinda testo de Barnum kaj simulilo de cold reading; ĉiu aserto portas nivelon de pruvoj.","tags":["manlegado","kulturo"]},"Radiestezie":{"line":"Trairu 18 nivelojn pri bastonsorĉado, kun glosaro, praktika taglibro kaj internaciaj aneksoj. Ĝi deklaras ekde la komenco, ke ĝi ne havas sciencan validigon.","detail":"Kurso en 18 niveloj pri bastonsorĉado, kun glosaro, praktika taglibro kaj internaciaj aneksoj; deklaras ekde la komenco, ke ĝi ne havas sciencan validigon.","tags":["kulturo"]},"Inforenergetica":{"line":"Eksciu kion asertas inforenergetiko, nekonvencia praktiko, en strukturita kurso. Ĝi ne havas sciencan validigon kaj ne estas kuracista konsilo.","detail":"Kurso pri inforenergetiko, nekonvencia praktiko sen scienca validigo; ne kuracista konsilo.","tags":["kulturo"]},"ECLIPSA":{"line":"Eksciu en kiu astrologia domo falas eklipso en via naska karto, plus la sekvaj 12 eklipsoj. La kalkulo estas proksimuma kaj la interpreto estas simbola, sen scienca validigo.","detail":"En kiu astrologia domo eklipso falas en naska karto, plus la sekvaj 12 eklipsoj. Loka, proksimuma astronomia kalkulo; simbola interpreto, astrologio ne havas sciencan validigon.","tags":["astrologio"]},"Afrodisiace-fara-frontiere":{"line":"Legu pri 22 manĝaĵoj kaj plantoj tradicie asociitaj kun deziro, ĉiu kun sia nivelo de pruvoj. Kultura gvidilo por plenaĝuloj, ne kuracista konsilo.","detail":"Kultura gvidilo pri 22 manĝaĵoj kaj plantoj tradicie asociitaj kun deziro, kun nivelo de pruvoj por ĉiu enskribo. Eduka, ne kuracista konsilo.","tags":["kulturo"]},"CalmWaves":{"line":"Ĉirkaŭa muziko generita surloke, por malstreĉiĝo kaj dormo. Ne kuracista aparato; la esplora sekcio ne estas sendepende kontrolita. Petu konsilon de kuracisto (epilepsio).","detail":"Generativa ĉirkaŭa muziko por malstreĉiĝo/dormo. Ne kuracista aparato; la esplora sekcio ne estas sendepende kontrolita. Petu kuracistan konsilon (epilepsio).","tags":["sono"]},"ASMR":{"line":"Kreu vian propran malstreĉan sonpejzaĝon el ĉirkaŭaj tavoloj, tuŝaj sonoj kaj duaŭdaj pulsoj. Ĝi havas dormo-tempigilon, kaj vi povas kunhavigi vian miksaĵon kun aliaj.","detail":"Malstreĉa sonmiksilo generita en reala tempo (Web Audio): ĉirkaŭaj tavoloj, tuŝaj sonoj, duaŭdaj pulsoj kaj dormo-tempigilo; kunhavigebla miksaĵo.","tags":["sono"]},"NOMIA":{"line":"Kia povus esti la unua kontakto inter homoj, artefaritaj inteligentoj kaj aliaj specoj de mensoj? 1001 imagitaj scenaroj, fikcio, ne faktoj. Funkcias ankaŭ senrete.","detail":"Koncepta simulilo de kontaktaj protokoloj Homo–AI–NHI, 1001 enskriboj, kunulo de la antologio “Printre inteligențe”. Fikcio/konjekto, ne kontrolitaj faktoj; senreta PWA, RO/EN.","tags":["fikcio","konjekto","PWA"]},"ValeaPlopului1972":{"line":"Rigardu kazon de OVNI el 1972 de ekstere, de interne kaj en simulado, rekonstruitan en 3D. Ĝi estas imagita hipotezo, ne pruvo.","detail":"3D-rekonstruo de la UAP-kazo de Valea Plopului (1972): ekstero, simulado, imagita interno. Konjekta, surbaze de nekontrolitaj publikaj fontoj, sen konsento de la nomitaj personoj; ne pruvo.","tags":["UAP","3D","fikcio"]},"HoroScop":{"line":"Kalkulu planedajn poziciojn por dato kaj loko, poste esploru la naskan karton, aspektojn kaj kongruon. Simbola astrologio, sen scienca bazo. Senrete.","detail":"Senreta persona efemerido: planedaj pozicioj kalkulitaj en la retumilo (reduktita precizeco), naska karto, aspektoj, sinastrio. Simbola astrologio, sen scienca validigo; permesilo MIT.","tags":["astrologio","efemerido","senrete"]},"Aurora":{"line":"Aŭskultu trankviligajn tonojn, milde pulsantajn sonojn kaj sekvu spiran gvidilon. Nur por malstreĉiĝo, ne kuracado. Funkcias senrete.","detail":"Sona sanktejo: ĉakraj tonoj, duaŭdaj pulsoj kaj spira gvidilo, senrete. Nur malstreĉiĝo, ne medicino; la frekvencoj ne havas sciencan validigon. Permesilo MIT; sendependa projekto.","tags":["meditado","sono","malstreĉiĝo"]},"NumeroLogIA":{"line":"Eksciu kion numerologio, ĉina astrologio BaZi kaj biorito diras pri via naskiĝdato, kun ĉiu kalkulo klarigita paŝo post paŝo. Simbola sistemo, sen scienca bazo.","detail":"Pitagora/kaldea numerologio, BaZi kaj biorito en 7 lingvoj, paŝo-post-paŝaj kalkuloj, portretoj eksporteblaj kiel JSON; laŭvola AI-orakolo per via propra modelo. Simbola sistemo, sen scienca validigo; permesilo MIT.","tags":["numerologio","AI","senrete"]},"FrequencyLaboratory":{"line":"Provu sonojn, efektojn kaj aŭdotestojn en malgranda sona laboratorio. La “kuracaj” efikoj estas nepruvitaj kaj ne anstataŭas kuraciston. Senrete.","detail":"Retumila sona laboratorio (oscilatoroj, duaŭdaj, efektoj, analizilo, aŭdotestoj), senrete. Nur informe: la “kuracaj” antaŭagordoj ne havas pruvitan kuracan efikon; ne kuracista aparato.","tags":["sono","laboratorio","senrete"]},"generator-frecvente":{"line":"Kreu puran tonon kaj pulsantajn duoblajn sonojn, aŭskultu konatajn antaŭagordojn kaj ricevu proksimuman kontrolon pri kiom bone vi aŭdas. Ne kuracista aparato. Senrete.","detail":"Retumila tongeneratoro (duaŭdaj, sekvencilo, EQ, indika aŭdotesto, serĉo de antaŭagordoj), senrete. Nur informe: la antaŭagordoj Solfeĝo/Schumann ne havas sciencan validigon; ne kuracista aparato.","tags":["sono","generilo","senrete"]},"ACORDAJ":{"line":"Foliumu pli ol mil spiritajn kursojn kaj iniciatojn, kun historia kunteksto kaj kritika rigardo. Ne rilata al la fonta retejo kaj sen scienca validigo. Senrete.","detail":"Senreta atlaso de 1134 spiritaj kursoj/iniciatoj (la listo de cursurispirituale.webnode.ro, sen rilato), kun historia kunteksto kaj kritika prijuĝo; sen scienca validigo.","tags":["spiriteco","atlaso","kritika prijuĝo"]},"Profund":{"line":"150 demandoj, kiuj kondukas la konversacion preter etparolado, inter amikoj aŭ en la familio. Ludu ilin sur ekrano aŭ presu ilin, kun laŭvola tempomezurilo.","detail":"Ludo de 150 demandoj por signifohavaj konversacioj (RO/EN/FR), rete aŭ presite, kun ludantoj kaj laŭvola tempomezurilo; adaptita el deepcards.org, la originaloj restas posedaĵo de siaj rajtuloj (MIT nur por la kodo kaj la originala parto).","tags":["konversacio","kartoj","trade-free"]},"Universul-Observabil":{"line":"Kiom granda estas la Universo, kiun ni povas vidi? Komparu tri mapojn (linia, plata, en spaco) kaj faru kosmologiajn kalkulojn. La ciferoj ne estas sendepende kontrolitaj.","detail":"Nodpaĝo prezentanta kaj komparanta la 1D-, 2D- kaj 3D-bildigojn de la Observebla Universo, kun senreta kosmologia kalkulilo; ciferoj kaj rekordoj estas el la katalogo de majo 2026, ne sendepende kontrolitaj. RO/EN.","tags":["astronomio","kosmologio","bildigo"]},"Universul-Observabil-1D":{"line":"Ekiru de ni kaj vojaĝu al la rando de la videbla Universo, preterpasante 112 galaksiojn metitajn sur unu akson. Ironia tono, rondigitaj valoroj, eduka celo.","detail":"1D-mapo de la observebla Universo: 112 galaksioj sur radiusa akso (tempo, distanco, ruĝenŝoviĝo), kun datumtabelo kaj eksporto CSV. Eduka, kun ironia tono; rondigitaj valoroj, rekordoj laŭ la dato de la katalogo (majo 2026).","tags":["astronomio","kosmologio","bildigo"]},"Universul-Observabil-2D":{"line":"Mapo de galaksioj en la satira eldono “Plata Tero”: ŝerco, la Tero ne estas plata. Zomu inter 111 galaksioj; distancoj estas proksimumaj. Senrete.","detail":"Interaga 2D-mapo de la observebla universo (111 galaksioj, logaritma skalo, datumoj de JWST) en satira eldono “Plata Tero”: parodio, la Tero ne estas plata; distancoj estas proksimumaj. RO/EN, senrete.","tags":["astronomio","satiro","kosmologio"]},"Universul-Observabil-3D":{"line":"Flugu inter pli ol 115 galaksioj sur 3D-mapo, kun gviditaj turoj kaj defioj. Valoroj estas proksimumaj.","detail":"Interaga 3D-mapo (WebGL) de la observebla universo: 115+ galaksioj, 12 horizontoj, 30 turoj, defioj en la gvidilo, eksporto GLB/CSV/BibTeX. Proksimumaj valoroj; rekordoj de JWST laŭ majo 2026.","tags":["astronomio","kosmologio","3D"]},"QSO":{"line":"Konservu la radiokontaktojn de via amatora radiostacio, kun tempo UTC, lokiloj kaj statistiko. Neoficiala; kalkuloj estas proksimumaj.","detail":"Neoficiala taglibro de amatora radiostacio: QSO-oj kun horloĝo UTC, importo/eksporto ADIF 3.1, lokiloj de Maidenhead, kontrolo de duoblaĵoj, statistiko. Parta tabelo de prefiksoj (ne DXCC); proksimumaj kalkuloj.","tags":["radio","taglibro"]},"Curatitor":{"line":"Vidu kion viaj fotoj kaj dosieroj malkaŝas (loko, kamerao, aŭtoro) kaj forigu tiujn datumojn antaŭ ol sendi ilin. Ĝi ne kaŝas vizaĝojn aŭ alian videblan enhavon.","detail":"Montras kaj forigas metadatumojn de dosieroj loke (GPS, kamerao, aŭtoro, programaro) sen rekodigi pikselojn aŭ sonon, kaj rekontrolas la rezulton. Ĝi ne anonimigas enhavon (vizaĝoj, sensila bruo).","tags":["metadatumoj","privateco"]},"Poteca":{"line":"Malfermu spurojn registritajn dum migrado aŭ biciklado kaj vidu la distancon, suriron kaj alteco-profilon. Vi ankaŭ povas tranĉi aŭ kunigi ilin. Sen mapo; surirado estas taksita.","detail":"Spektilo kaj redaktilo por spuroj GPX/GeoJSON/KML/CSV: statistiko, alteco-profilo, tranĉo, kunigo, simpligo, eksporto. Sen baza mapo; surirado/malsurirado estas taksoj.","tags":["GPX","spuroj"]},"Orar":{"line":"Kalendaro kaj semajna planilo, kiun vi povas vidi laŭ tago, semajno aŭ monato, kun rumanaj ŝtataj ferioj. Alarmoj sonas nur dum la paĝo restas malfermita.","detail":"Kalendaro kaj semajna planilo: vidoj de monato/semajno/tago/tagordo, ripetoj laŭ RFC 5545, horzonoj, rumanaj ŝtataj ferioj, importo/eksporto .ics. Alarmoj sonas nur dum la langeto estas malfermita.","tags":["kalendaro","tempo"]},"Alfabete":{"line":"Lernu kaj ekzercu Morse, brajlon, la fonetikan alfabeton, flagan semaforon kaj malnovajn ĉifrojn, poste presu folion. Malnovaj ĉifroj ne protektas sekretojn.","detail":"Referenco, konvertilo, trejnilo kaj presebla folio por Morse, brajlo (grado 1), fonetikaj alfabetoj, semaforo, Baudot, nombrobazoj kaj klasikaj ĉifroj. Klasikaj ĉifroj ne ofertas sekurecon.","tags":["kodoj","lernado"]},"Fabrica":{"line":"Skribu kurson kiel simplan tekston kaj igu ĝin paĝo kun lecionoj, fina testo kaj presebla atestilo. La atestilo ne havas oficialan valoron.","detail":"Fabriko de kursoj kaj kvizoj: skribu kurson en simpla Markdown kaj eksportu ĝin kiel unu memhavan HTML-dosieron kun loka progreso, fina testo kaj presebla atestilo (sen akredita valoro).","tags":["kursoj","aŭtorado"]},"Bolta":{"line":"Kiel aspektis la ĉielo super vi, en iu ajn loko kaj tago inter 1900 kaj 2100? Vidu la Sunon, Lunon, planedojn kaj stelojn, plus la eklipson de 2027. Valoroj estas kalkulitaj, ne oficialaj. Senrete.","detail":"Senreta planetario por iu ajn loko kaj tempo inter 1900 kaj 2100: Suno, Luno, planedoj, 1 627 steloj, konstelacioj, eventoj kaj paĝo pri la eklipso de 2027. Kalkulitaj valoroj, ne oficialaj.","tags":["astronomio","planetario"]},"BRAZDA":{"line":"Malĉifru la Oran Diskon de Voyager paŝo post paŝo, poste ĉifru novan diskon por enketilo lanĉita nun. La bildoj en la unuaj paŝoj estas skemaj, ne tiuj de NASA.","detail":"Malĉifrilo kaj ĉifrilo en 12 paŝoj por la Ora Disko de Voyager: rapido, la hidrogena horloĝo, la pulsara mapo, la signalo de bildo, kalibrado per la cirklo, linio-post-linia malĉifrado, koloro, via propra dosiero, kontribuoj kaj la ĉifrado de disko 2026–2027.","tags":["Voyager","signalo"]},"Arbore":{"line":"Kreu vian genealogian arbon, kun personoj, familioj, tempolinio kaj parenceca kalkulilo en la rumana. Datumoj restas nur en ĉi tiu retumilo, sen sinkronigo.","detail":"Loka genealogio: personoj, familioj, importo/eksporto GEDCOM 5.5.1, SVG-diagramoj, tempolinio, parenceca kalkulilo (nur rumana terminologio). Sen sinkronigo; datumoj restas en ĉi tiu retumilo.","tags":["genealogio","GEDCOM"]},"Gospodar":{"line":"Gardu la monon de la hejmo: kontoj, elspezoj, monataj buĝetoj kaj raportoj. Konto ne necesas, sed se vi perdas vian pasvorton, vi perdas viajn datumojn. Ne financa konsilo.","detail":"Loka hejma buĝeto: kontoj, kategorioj, transakcioj, importo CSV, monataj buĝetoj, raportoj kaj kalkuliloj kun travideblaj formuloj. Sen konto aŭ sinkronigo; perdita pasvorto signifas perditajn datumojn. Ne financa konsilo.","tags":["buĝeto","persona financo"]},"Decibel":{"line":"Mezuru kiom laŭta estas la ĉirkaŭa bruo kaj vidu el kiaj sonoj ĝi konsistas. Ĝi havas ankaŭ indikan aŭdoteston. Ne atestita aparato; rezultoj dependas de la mikrofono.","detail":"Sonnivelmezurilo, spektra analizilo (1/3 okto, FFT) kaj indika aŭdotesto. Ne atestita mezurilo kaj sen jura aŭ kuracista valoro; mezuroj dependas de la mikrofono kaj kalibrado.","tags":["sono","mezurado"]},"Provenienta":{"line":"Ĉu vi havas bildon kaj volas scii, kiu subskribis ĝin kaj kiujn redaktojn ĝi deklaras? Kontrolu la ligitan ciferecan subskribon. Eksperimenta, testita nur per specimenaj dosieroj.","detail":"Loka, eksperimenta kontrolilo de C2PA / Content Credentials: montras kiu subskribis kaj kiujn redaktojn oni deklaris, kaj kontrolas la subskribon kaj la ligon al la bajtoj de la dosiero. Testita nur per sintezaj dosieroj; sen fidlisto.","tags":["C2PA","deveno"]},"Lexicon":{"line":"Alportu viajn proprajn vortarojn kaj serĉu vortojn en ili, eĉ se vi tajpas sen diakritaj signoj aŭ kun eraroj. Ĝi venas nur kun malgranda demonstra aro. Senrete.","detail":"Senreta vortara motoro: alportu viajn proprajn vortarojn (TSV/CSV, JSON, StarDict, dictd, XDXF) kaj serĉu laŭ prefikso, sen atento al supersignoj, malprecize aŭ plentekste. La kunportita aro (345 enskriboj) estas demonstro, ne kompleta vortaro.","tags":["vortaro","lingvo"]},"VERIGA":{"line":"Trovas rompitajn ligilojn en retejo aŭ dosierujo, plus dosierojn restintajn sen celo. Funkcias en Windows, macOS kaj Linux; postulas iom da komputila sperto.","detail":"Kontrolilo de ligiloj (clean-room) por retejoj kaj lokaj dosierujoj, skribita en Rust: komandlinio, denaska labortabla aplikaĵo (egui) kaj unudosiera HTML-versio. Kontrolas ligilojn de HTML kaj CSS, alidirektojn, ankrojn #fragment, orfajn dosierojn, robots.txt kaj sitemap. Windows, macOS kaj Linux; permesilo MIT.","tags":["kontrolo de ligiloj","MIT"]},"TEZAUR":{"line":"Helpanto por via tezo, kiu skribas nur el viaj propraj libroj kaj artikoloj, kun kontroleblaj citaĵoj. Funkcias en via komputilo; viaj dokumentoj neniam forlasas ĝin. Laboro en progreso.","detail":"Loka esplora helpanto por skribi tezon, skribita en Rust, kun citaĵ-fundamentitaj respondoj: ĝi indeksas viajn librojn kaj artikolojn (PDF, EPUB, DOCX, txt), reakiras pasaĝojn kaj skribas nur el ili, kun kontrolitaj citaĵoj [n] kaj listo de referencoj. Funkcias en via propra komputilo per loka modelo (Ollama, Jan, LM Studio); viaj dokumentoj neniam forlasas ĝin. Versio 0.x; permesilo MIT.","tags":["esplorado","MIT"]},"LegatorOCR":{"line":"Skanu libron kaj ricevu puran PDF kun rektigitaj paĝoj kaj serĉebla teksto. Funkcias en Windows, macOS kaj Linux; viaj skanaĵoj restas ĉe vi.","detail":"Clean-room postprilaborilo skribita en Rust por skanitaj libroj: disigas duoblajn paĝojn, rektigas klinon, tondas, starigas marĝenojn, purigas kaj binarigas, poste eksportas PDF aŭ bildojn kun serĉebla OCR-teksta tavolo. Grafika aplikaĵo (Windows, macOS, Linux) kaj komandlinio, en 8 lingvoj. Teksta rekono (OCR) bezonas la apartan programon Tesseract; ĉio alia funkcias sen ĝi. Versio 0.x; permesilo MIT.","tags":["skanado","MIT"]},"Fenarium":{"line":"Atlaso kaj laborrenkontiĝo pri subjektivaj perceptoj tra ĉiuj sensoj, ekde Fosfenismo: kurso de 13 moduloj, gviditaj eksperimentoj, vida simulilo kaj hazardigita A/B-laboratorio de memeksperimentoj. Eduka, ne kuracista aparato.","detail":"Atlaso de fenoj (fosfenoj, postbildoj, tinituso-similaj sonoj kaj pli), kurso de 13 moduloj, laboratorio de memeksperimentoj; ne kuracista aparato.","tags":["percepto","MIT"]},"MENSURA":{"line":"Mezuru vian IQ, EQ, CQ, RQ, ekzekutivajn funkciojn kaj sensojn per 18 testoj en 6 fakoj, kun kunmetitaj indeksoj kaj 95% konfidencaj intervaloj. Provizoraj normoj, nur indike, ne diagnozo.","detail":"18 testoj en 6 fakoj (IQ, EQ, CQ, RQ, ekzekutivaj funkcioj, sensoj), indeksoj kun konfidencaj intervaloj, eksporto/importo JSON; provizoraj normoj.","tags":["testoj","MIT"]},"Cronosala":{"line":"Tempomezuriloj por sportejo: ripozo inter serioj, HIIT, Tabata, EMOM, AMRAP, cirkvitoj kaj metronomo, plus trejna taglibro kun kg kaj ripetoj.","detail":"Tempomezuriloj por sportejo kaj trejna taglibro en unu HTML-dosiero: adapta ripozo inter serioj, Interval/HIIT, Tabata, EMOM, AMRAP, stacidomaj cirkvitoj, tempo, metronomo, 4-semajna monata programo, katalogo de ekzercoj kaj QR-kodoj por maŝinoj. Datumoj restas en la retumilo; la interfaco estas en la rumana.","tags":["sporto","tempo"]},"ScutSonor":{"line":"Laŭta sono kaj lampa stroboskopo por renkontoj kun agresemaj hundoj, plus konduta gvidilo. Helpilo, ne garantiita ŝildo.","detail":"Generas balaon 2–8 kHz, eksperimentan ultrasonon, sirenon kaj parolil-teston, kun limigilo, kiu tenas laŭtecon, lampan stroboskopon (2,5 Hz), taglumreĝimon kaj sekurecan gvidilon. Unu dosiero, sen spurado. Pruvoj, ke sono timigas hundojn, estas malfortaj.","tags":["sekureco","sono"]},"MIRAJ":{"line":"Kiel la retino vidas kaj kiel la cerbo konstruas la bildon: fovea, blinda makulo, iluzioj kaj kvizo, en tri niveloj.","detail":"Interaga klarigo de vido en tri niveloj (komencanto, meznivela, altnivela): retino, fovea, blinda makulo, optikaj iluzioj, resumo kaj kvizo de 10 demandoj. Unu dosiero, interfaco en la rumana kaj la angla.","tags":["vido","edukado"]},"ANTROPOS":{"line":"Orienta scienca profilo, kalkulita loke: biologia aĝo PhenoAge, voĉo, mana skribo, horloĝa desegno, personeco TIPI kaj reaga tempo.","detail":"Eduka ekzamena ilo, ne diagnozo: biologia aĝo PhenoAge kun plaŭzibleca gardilo, voĉa analizo, grafometrio de mana skribo, testoj de horloĝo kaj de desegno de persono, TIPI, reagaj testoj, presebla raporto kaj eksporto JSON. Datumoj restas en la retumilo.","tags":["ekzamenado","biologio"]},"DESCANTAR":{"line":"Divenado per fazeoloj kun 41 fazeoloj (metodo 3×3, olteneca varianto) kaj 12 tradiciaj sorĉoj, kiel objekto de folklora studo.","detail":"Rumana divenado per fazeoloj laŭ tri metodoj (3×3 laŭ la libro, Oltenio, tri stakoj), legoj laŭ Kapo, Koro kaj Piedoj, 12 tradiciaj sorĉoj, luna fazo, deklamanta kalkulilo, sorĉa generilo, historio kaj kopiebla gvidilo. Folklora enhavo tradukita en 8 lingvojn per AI, ne reviziita de denaskaj parolantoj.","tags":["folkloro","fazeoloj"]},"Index-fara-frontiere":{"line":"Katalogo de unudosieraj HTML-aplikaĵoj: la kolekto chiuta.github.io plus eksteraj rimedoj, kun serĉo kaj etikedoj.","detail":"Ok projektoj el la kolekto de la aŭtoro kaj ok eksteraj rimedoj, klare markitaj, kun viva serĉo, klakeblaj etikedoj, ŝaltilo RO/EN, malhela/hela etoso kaj enskribo, kiu katalogas sin mem. Neniuj retaj petoj. Senmova momentfoto de la 5-a de julio 2026.","tags":["katalogo","rimedoj"]},"DECUPAJ":{"line":"Igu podkaston, sonan aŭ video, vertikalaj filmetoj kun subtekstoj, rekte en la retumilo, sen konto kaj sen akvomarko. Viaj dosieroj neniam forlasas vian aparaton.","detail":"Vertikalaj reels el podkasto (sono aŭ video) en unu HTML-dosiero: elektu la segmenton sur la ondformo, ricevu sugestojn de momentoj, lokan transskribon per Whisper, stilitajn subtekstojn, 4 bildformatojn (9:16, 4:5, 1:1, 16:9), eksportan vicon kaj MP4 per WebCodecs. Interfaco en 8 lingvoj.","tags":["reels","video"]},"LECTOR":{"line":"Libroj voĉlegataj rekte en la retumilo: EPUB, DOCX, PDF, TXT aŭ algluita teksto, sen konto kaj sen servilo. La teksto neniam forlasas vian aparaton.","detail":"Aŭskultu librojn voĉlegatajn el unu HTML-dosiero: EPUB, DOCX, PDF (kun rumana OCR por skanaĵoj), TXT; voĉoj de la aparato aŭ Piper ro_RO, la parolata vorto emfazita, dormo-tempigilo, ĉapitroj, legosignoj, prononca vortaro, loka biblioteko kaj dislekso-amikaj etosoj. Interfaco en 8 lingvoj.","tags":["sono","libroj"]},"FARFURIA":{"line":"Senpaga cifereca dietisto: personigitaj kalorioj kaj makroj, 7-taga manĝoplano, manĝa taglibro kaj sekvado de pezo. Ne anstataŭas kuraciston aŭ dietiston.","detail":"Cifereca dietisto en unu HTML-dosiero: celoj de kalorioj kaj makroj (Mifflin–St Jeor, aktiveca nivelo, celo), 7-taga manĝoplano kun filtriloj de dieto kaj alergenoj, manĝa datumbazo, manĝa taglibro kaj sekvado de pezo. Sekurecaj reguloj por neplenaĝuloj, historio de manĝmalordoj kaj rena malsano. Interfaco en 8 lingvoj.","tags":["nutrado","sano"]},"VITALIS":{"line":"Privata kunulo pri sano, longviveco kaj biohakado: naŭ pilieroj rangigitaj laŭ pruvoj, kalkuliloj, vivstila poentaro kaj ĉiutaga rito. Ne kuracista konsilo.","detail":"Kunulo pri sano kaj longviveco en unu HTML-dosiero: naŭ pilieroj rangigitaj laŭ pruvoj, kalkuliloj (HOMA-IR, TyG, talio-al-alteco, Mifflin–St Jeor, kor-ritmaj zonoj, dormaj cikloj, proteino), fasta tempomezurilo, spira ritmilo, poentaro 360 kun radara diagramo, referencaj intervaloj de biomarkiloj kaj sekvilo de ĉiutaga rito. Neoficiala kunulo de la evento BioHacking360. Interfaco en 8 lingvoj.","tags":["sano","longviveco"]},"REZONANTA":{"line":"Gvidilo kaj iloj por komunikado kaj amaskomunikiloj: mesaĝo, kanaloj, komuniko, intervjuo, klareco, plano kaj krizo.","detail":"Kiel igi homojn aŭskulti, en unu HTML-dosiero: 12 principoj kun praktika testo, la “mesaĝa domo” (30-sekunda prezento, afiŝo, mallonga kaj parola versio), rekomendoj de amaskomunikilaj kanaloj, generilo de komunikoj laŭ inversa piramido, intervjua folio, analizilo de klareco de teksto, komunika plano kun eksporto teksto/CSV kaj la paŝoj de la unua horo de krizo. Interfaco en 8 lingvoj.","tags":["komunikado","amaskomunikiloj"]},"Claritas":{"line":"Ĉio-en-unu alirebleca retumila etendaĵo: korekto de kontrasto, legreĝimo, voĉlegado kaj WCAG-kontrolo. Sen telemetrio, sen reto, sen konto.","detail":"Senpaga alirebleca etendaĵo por la retumilo: aŭtomata korekto de kontrasto (WCAG AA/AAA), altkontrastaj etosoj, filtriloj por kolorblindeco, pli granda teksto kaj dislekso-amikaj tiparoj, legoregilo, masko kaj lenso, legreĝimo, voĉlegado, grandaj klakceloj kaj skanado per unu ŝaltilo, kontrolo WCAG 2.2, lokaj ekrankopioj kaj ekranregistrado. Por Chromium, Firefox kaj Safari; interfaco en 8 lingvoj.","tags":["alirebleco","etendaĵo"]},"TurboCursa":{"line":"Pseŭdo-3D arkada aŭtovetkuro skribita en Rust: pejzaĝoj generitaj de semo, 11 reĝimoj, kariero de divizioj kaj 2 ludantoj. Originala, sen kodo aŭ aktivaĵoj de alia ludo.","detail":"Clean-room pseŭdo-3D arkada aŭtovetkuro skribita en Rust: originala motoro, arto, muziko kaj nomo, ĉio generita de semo (19 pejzaĝoj), kampanjo, tempoprovo, senfina, Rush Hour, slalomo, spegula, Blackout, Zen, kontraŭ CPU, dupersona dividita ekrano kaj kariero de divizioj. Funkcias denaske aŭ kiel reta dosiero; interfaco en 8 lingvoj.","tags":["konkurso","Rust"]},"ANTENA":{"line":"Laboro en progreso: NEC-2-kongrua solvilo de dratantenoj (metodo de momentoj) kun retumila fasado. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: NEC-2-kongrua solvilo de dratantenoj (metodo de momentoj) kun retumila fasado. Ĝis nun nur antaŭ-alfa skeleto.","tags":["radio","antenoj"]},"ARBITRU":{"line":"Laboro en progreso: universala regulmotoro por tabulaj, kartaj, ludkubaj kaj puzlaj ludoj, kun deklara regullingvo. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: universala regulmotoro por tabulaj, kartaj, ludkubaj kaj puzlaj ludoj, kun deklara regullingvo. Ĝis nun nur antaŭ-alfa skeleto.","tags":["ludoj","reguloj"]},"ASTROLABIU":{"line":"Laboro en progreso: motoro de ĉielaj eventoj (temposkaloj, eklipsoj, leviĝo kaj subiro, kalendaroj), en pura Rust. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: motoro de ĉielaj eventoj (temposkaloj, eklipsoj, leviĝo kaj subiro, kalendaroj), en pura Rust. Ĝis nun nur antaŭ-alfa skeleto.","tags":["astronomio","kalendaroj"]},"ECOGRAMA":{"line":"Laboro en progreso: spektrograma redaktilo kaj sona restaŭrado: elektu sur la spektrogramo, riparu, eksportu. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: spektrograma redaktilo kaj sona restaŭrado: elektu sur la spektrogramo, riparu, eksportu. Ĝis nun nur antaŭ-alfa skeleto.","tags":["sono","restaŭrado"]},"ecou-spectral-rs":{"line":"Laboro en progreso: denaska Rust-spektrograma redaktilo kun kromaĵoj por bruoredukto kaj detekto de voĉo. Ĝi havas kodan skeleton kaj kromaĵan formaton, sed ankoraŭ neniun finitan funkcion.","detail":"Laboro en progreso: denaska Rust-spektrograma redaktilo kun kromaĵoj por bruoredukto kaj detekto de voĉo. Ĝi havas kodan skeleton kaj kromaĵan formaton, sed ankoraŭ neniun finitan funkcion.","tags":["sono","Rust"]},"MARTOR":{"line":"Laboro en progreso: jurmedicina reta kapto en WARC/WACZ kun haŝoj, subskriboj kaj fidindaj tempomarkoj, kontrolebla senrete. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: jurmedicina reta kapto en WARC/WACZ kun haŝoj, subskriboj kaj fidindaj tempomarkoj, kontrolebla senrete. Ĝis nun nur antaŭ-alfa skeleto.","tags":["arkivado","pruvoj"]},"NEAMURI":{"line":"Laboro en progreso: motoro de parenceco, de vojo en genealogia arbo ĝis la ĝusta parenca termino en multaj lingvoj. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: motoro de parenceco, de vojo en genealogia arbo ĝis la ĝusta parenca termino en multaj lingvoj. Ĝis nun nur antaŭ-alfa skeleto.","tags":["parenceco","genealogio"]},"TACTIL":{"line":"Laboro en progreso: tuŝebla eliga tavolo: brajlaj formatoj (BRF, Unicode), ekranoj, embosiloj kaj vibro de tuŝekrano. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: tuŝebla eliga tavolo: brajlaj formatoj (BRF, Unicode), ekranoj, embosiloj kaj vibro de tuŝekrano. Ĝis nun nur antaŭ-alfa skeleto.","tags":["brajlo","alirebleco"]},"atelier-verificare":{"line":"Kontrolu fotojn, filmojn, ligilojn kaj domajnojn en via retumilo, nenio alŝutata: reala dosiertipo kaj SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (nur legado), analizo de erarnivelo. Ĝi ne povas pruvi, ke foto estas aŭtentika. Alfa.","detail":"Kontrola ilaro por ĵurnalistoj kaj atentaj legantoj, kiu funkcias loke. Aldonu bildojn, filmojn, ligilojn, domajnojn aŭ tekston kaj ricevu trovaĵojn kun nivelo de zorgo por ĉiu: la reala dosiertipo, SHA-256, EXIF kaj GPS-pozicio, XMP kaj IPTC, spuroj de AI-bildgeneriloj, manifestoj de Content Credentials (C2PA; legitaj, ne validigitaj), analizo de erarnivelo por JPEG, video-metadatumoj kun ŝlosilkadroj por inversa bildserĉo, kaj anatomio de ligiloj. Du laŭvolaj retaj kontroloj (resumo de DNS, Internet Archive) funkcias nur post kiam vi markas konsentan skatolon. La raporto (Markdown, JSON aŭ PDF) listigas la limojn de la metodo. Ĝi ne povas pruvi, ke foto estas aŭtentika: mankantaj metadatumoj diras malmulton kaj metadatumoj povas esti falsitaj. Alfa; naŭ el la dek unu kontroloj funkcias senrete; dosieroj restas en la retumilo.","tags":["ĵurnalismo","kontrolo","fotoj"]},"balanta":{"line":"Komparu AI-modelojn blinde: algluu la respondojn de du ĝis ok modeloj al 92 rumanaj, anglaj kaj hungaraj promptoj, voĉdonu A aŭ B, kaj ricevu rangotabelon kun intervaloj. Alfa; funkcias senrete.","detail":"Blinda apudmeta takso de AI-modeloj en la rumana. Vi mem algluas la respondojn de ĉiu modelo (nenio estas alvokata: neniuj API-ŝlosiloj, neniuj kontoj), la aplikaĵo kaŝas la nomojn de la modeloj en la respondoj, fiksas la ordon el semo kaj registras vian voĉdonon. La rangotabelo uzas Bradley–Terry kaj Elo kun 95% bootstrap-intervaloj, plus gajnoprocenton, pozician biason kaj tabelojn de rektaj duelaj matĉoj. Voĉdonoj kaj respondoj estas malfermitaj dosieroj JSON Lines. Kun malmultaj voĉdonoj aŭ promptoj la rangotabelo diras nenion ĝeneralan. Alfa; datumoj restas en la retumilo; sen spurado.","tags":["AI","takso"]},"calendarium":{"line":"Tajpu daton en iu el dek unu kalendaroj (gregoria, julia, hebrea, hegira, persa, ĉina, maya, Marsa…) kaj vidu ĝin en ĉiuj aliaj, kun monata vido. Alfa; funkcias senrete.","detail":"Konvertas datojn inter dek unu kalendaroj (gregoria, julia, Reviziita julia, hebrea, hegira, persa, kopta, etiopa, ĉina, maya kaj la Marsa Sol Date), montras la Julian Day, semajntagon kaj ISO-semajnon, kaj havas monatan vidon kun dua kalendaro sub ĉiu tago. Inkluzivas rumanajn notojn (malnova kaj nova stilo, la ŝanĝo de 1919, Pasko) kaj atlason de la kalendaroj, unu kromaĵo por kalendaro. Valoroj estas kalkulitaj, kun deklaritaj limoj (la hegira kalendaro estas la tabela; intervaloj estas gardataj). Alfa, en 8 lingvoj, funkcias senrete; sen spurado.","tags":["kalendaroj","tempo"]},"glosar":{"line":"Senreta vortaro por la aromana, megleno-rumana kaj romani: serĉo sen diakritaj signoj, vidu kiuj bazaj vortoj mankas, aldonu vortojn kun fonto kaj registraĵo. Alfa.","detail":"Vortaroj por minoritataj kaj endanĝerigitaj lingvoj, faritaj de iliaj parolantoj. Serĉas ignorante diakritajn signojn, montras fidindecon (malneto, kun fonto, reviziita), havas tabelon de kovro de 50 bazaj konceptoj kaj lasas aldoni vortojn kun fonto, permesilo kaj registraĵo (ĝis 50 KB). Eksportas TSV kaj Anki-dosierojn kaj kontribuan dosieron por la projekto. La komencaj listoj estas malgrandaj — numeraloj kaj kelkaj vortoj, ĉiu kun publikigita fonto — kaj neniu parolanto ankoraŭ reviziis ilin. Alfa; funkcias senrete; datumoj restas en la retumilo ĝis vi elŝutas ilin.","tags":["lingvoj","vortaroj"]},"graiul":{"line":"Senreta arkivo de rumana folkloro (proverboj, sorĉoj, enigmoj, kristnaskaj kantoj) kun fonto, departemento kaj konsento. Ĝi komencas per dek proverboj; vi povas aldoni pli. Alfa.","detail":"Serĉo ignoranta diakritajn signojn, kun filtriloj laŭ tipo, departemento kaj fidindeco; proverbo de la tago (sama por ĉiuj en difinita dato), skema kahela mapo de 41 departementoj kaj Bukareŝto, kaj aldona formularo, kiu postulas fonton kaj, por sorĉoj kaj ĉio kolektita de persono, konsenton. Eksportas kontribuan dosieron kaj TSV. La komencaj datumoj estas dek rumanaj proverboj el Wikiquote; neniu estis reviziita de folkloristo. Alfa; funkcias senrete; datumoj restas en la retumilo ĝis vi elŝutas ilin.","tags":["folkloro","arkivo"]},"indicativ-international":{"line":"Ekzercu demandojn de la ekzameno de amatora radio kun kvinkesta ripeta horaro kaj tempigitaj provekzamenoj; importu demandpakojn en unu komuna JSON-formato. 50 ekzercaj demandoj inkluzivitaj; ne oficiala demandaro. Alfa.","detail":"Trejnilo kaj ekzamen-simulilo por demandoj de licenco de amatora radio, kun komuna pako-formato por ke ĉiu lando povu aldoni sian propran demandaron. “Trejni” ripetas ĝustajn respondojn post 1, 3, 7, 14 kaj 30 tagoj kaj klarigas ĉiun respondon kun ĝia fonto; “Ekzameno” estas tempigita testo kun sukcesa limo; “Pakoj” importas kaj kontrolas pakojn kaj sekurkopias vian progreson. La enkonstruita pako enhavas 50 originalajn ekzercajn demandojn skribitajn por ĉi tiu projekto — ne oficiala demandaro — kaj neniu landa pako ankoraŭ estas inkluzivita. Alfa; funkcias senrete; progreso restas en la retumilo.","tags":["radio","ekzamenoj"]},"proiector-fara-frontiere":{"line":"Telefonoj de la klasĉambro fariĝas komuna ekrano, sen servilo kaj sen konto: tempomezurilo, enketo, kvizo, notoj kaj tabulo, parigitaj per QR-kodo aŭ algluita teksto en la sama reto. Alfa: ankoraŭ ne provita en realaj telefonoj.","detail":"Komuna ekrano por la klasĉambro, sen servilo kaj sen konto. La instruisto malfermas la paĝon ĉe la projektoro; la telefono de ĉiu lernanto aliĝas per interŝanĝo de kodo (QR-kadroj, foto de la kodo aŭ algluita teksto), ĝis 30 telefonoj samtempe. Kvin agadoj estas inkluzivitaj: retronombra tempomezurilo, enketo kun vivaj stangoj, kvizo (demandoj el dosiero JSON, simpla teksto aŭ CSV; la ĝusta respondo restas ĉe la projektoro ĝis ĝi estas malkaŝita; rapida bonuso kaj poentaro), glueblaj notoj kaj tabulo kun unu koloro por telefono. Rezultoj povas esti konservitaj kiel CSV, teksto aŭ PNG. Ĉiu agado funkcias en izolita kadro kun nur la permesoj, kiujn ĝi deklaras, kaj nova agado estas unu priskribilo kaj unu skripto. La instruisto povas ŝlosi aŭ forigi telefonon kaj fini la seancon; ĉiu aparato elektas sian propran lingvon (ok) kaj aspekton (malhela, alta kontrasto, granda teksto). Ĝi funkcias senrete post la malfermo kaj povas esti instalita. Alfa: testita en Chromium kun realaj konektoj en unu maŝino, ne en realaj telefonoj, aliaj retumiloj aŭ lernejaj retoj. Parado postulas la saman lokan reton (sen relajso), montras la IP-adreson de ĉiu aparato al la alia kaj ne kontrolas, kiu estas la alia aparato. La kviz-formato de “Undava” ne estas subtenata: neniu specifo troviĝis.","tags":["klasĉambro","projekciado","kvizo"]},"regula":{"line":"Ludu kvin klasikajn duopajn ludojn (Nine Men’s Morris, Alquerque, Fanorona, Mū tōrere, Hnefatafl) kontraŭ la komputilo aŭ amiko; aldonu vian propran ludon kiel JSON. Alfa; funkcias senrete.","detail":"Unu regulmotoro por tradiciaj tabulaj ludoj: ĉiu ludo estas JSON-dosiero, kaj la regultekstoj en ok lingvoj estas generitaj el la samaj datumoj, kiujn la motoro ludas, do teksto kaj ludo ne povas kontraŭdiri. Ĉiu flanko povas esti persono, hazarda ludanto aŭ la komputilo je du niveloj; malfari, refari, sugesto kaj movlisto, kiun vi povas kopii. Vi povas alglui, validigi kaj ludi vian propran ludon. La ludoj estas rekonstruoj, ne turnirreguloj, kaj ĉiu deklaras kiom certaj estas ĝiaj reguloj. Alfa; funkcias senrete; sen spurado.","tags":["ludoj","reguloj"]},"vietar-packs":{"line":"Foliumu, importu, kontrolu kaj kreu regionajn speciopakojn por VietAR: nomoj en pluraj lingvoj, markoj de toksecaj, similaĵoj. Kvin malnetaj komencaj pakoj kun 71 specioj. Alfa; funkcias senrete.","detail":"Regionaj speciopakoj por VietAR: nomoj en pluraj lingvoj, marko de toksecaj, danĝeraj similaĵoj, kaj loko por licencitaj fotoj kaj sonligiloj. Foliumu kaj serĉu kvin komencajn pakojn (Rumanio: plantoj kaj fungoj, birdoj, mamuloj; Bulgario kaj Moldavio: skeletoj), importu pakon, kontrolu ĝin per la samaj reguloj kiel la deponejo, aŭ kreu unu por lerneja klaso aŭ naturklubo. La komencaj pakoj estas malnetoj sen fotoj aŭ sonoj, kaj “ne markita tokseca” neniam signifas manĝebla aŭ sekura. La aplikaĵo VietAR ankoraŭ ne povas importi pakojn. Alfa; funkcias senrete.","tags":["naturo","specioj"]},"PatruZeci":{"line":"La ilustrita, animita atlaso de uzoj de WD-40: gvidilo de 147 kartoj kaj la oficiala listo de 1993 uzoj, ĉiu kun propra animita sceno. Neoficiala, senrete, sen konto.","detail":"Ilustrita, animita atlaso de uzoj de la ŝpruco WD-40 en unu senreta dosiero: gvidilo de 147 kartoj en 14 kategorioj (kun risknivelo kaj kion la ŝpruco faras), la oficiala listo “2000+ uzoj” kun 1993 enskriboj, kaj sekcio de 25 pliaj uzoj, mitoj kaj avertoj el retartikoloj. 131 animitaj sceno-variantoj, filtriloj laŭ kategorio kaj funkcio, interfaco en 8 lingvoj. Neoficiala, sendependa aplikaĵo.","tags":["WD-40","DIY"]},"ODISEEA":{"line":"Dokumentario de ĉirkaŭ 4,5 minutoj pri Voyager 1 kaj 2, en unu HTML-dosiero: scenoj generitaj de la grafikkarto, 2D- kaj 3D-eksporto por VR-okulvitroj, en 8 lingvoj.","detail":"Dokumentario de ĉirkaŭ 4,5 minutoj pri la enketiloj Voyager 1 kaj 2, en unu HTML-dosiero, kiu funkcias loke en la retumilo, sen servilo kaj sen instalo. Procedaj scenoj generitaj de la grafikkarto (WebGL): planedoj, enketilo, raketo, DSN-anteno, la Ora Disko, la heliosfero, la Pale Blue Dot. Publikaj bildoj de NASA/JPL kaj Wikimedia Commons, aŭ via propra bildo por ĉiu sceno. Eksporto en 2D, duona (1920×1080) kaj plena (3840×1080) 3D apudmeta, kaj telefona reĝimo por VR-okulvitroj kiel VR BOX; ĉirkaŭa muziko generita en la retumilo, laŭvola rakontado. Interfaco, rakontado, subtekstoj kaj kreditoj en 8 lingvoj.","tags":["Voyager","dokumentario"]},"EXIF-CURAT":{"line":"Laboro en progreso: ilo por vidi kaj forigi la kaŝitajn datumojn en dosieroj (bildoj, PDF, Office, video: EXIF, GPS, XMP), kun memor-sekuraj analiziloj, skribita en Rust. Ĝis nun nur antaŭ-alfa skeleto.","detail":"Laboro en progreso: ilo por vidi kaj forigi la kaŝitajn datumojn en dosieroj (bildoj, PDF, Office, video: EXIF, GPS, XMP), kun memor-sekuraj analiziloj, skribita en Rust. Ĝis nun nur antaŭ-alfa skeleto.","tags":["metadatumoj","privateco"]},"PORUMBEL":{"line":"Aŭtomate movas la fotojn, kiujn vi faras per Open Camera en via telefono, en dosierujon en via komputilo, unu dosierujo por seanco, kaj malfermas ilin en LegatorOCR. Sen konto, sen nubo, sen triaj kestoj.","detail":"Malgranda programo skribita en Rust, sen triapartiaj kestoj (Windows, macOS, Linux), kiu alportas la fotojn, kiujn vi faras per Open Camera, en vian komputilon: per Wi-Fi (alŝuta paĝo aŭ WebDAV, kun QR-kodo), per ADB (USB aŭ Wi-Fi) aŭ el sinkronigita dosierujo (Syncthing ktp.). Ĝi metas la fotojn en unu dosierujon por fotseanco kaj malfermas ĉiun finitan seancon en LegatorOCR (disigo, rektigo, tondo, PDF kun OCR). Loka kontrolpanelo kaj komando “porumbel doctor” por diagnozo; nenio forlasas vian reton. Versio 0.x; permesilo MIT.","tags":["fotoj","transdono"]},"colibri-companion":{"line":"Afabla labortabla aplikaĵo por colibri, la loka inferenca motoro: elektu modelon taŭgan por via komputilo, elŝutu ĝin per unu klako kaj babilu kun ĝi. Sen konto, sen nuba servo.","detail":"Labortabla aplikaĵo skribita en Rust por colibri (JustVugg/colibri): ĝi trovas Python kaj colibri, montras nur la modelojn, kiuj taŭgas por la memoro de via komputilo, elŝutas ilin kun paŭzo kaj daŭrigo, startas la lokan servilon kaj malfermas la babilon (fluantaj respondoj, Markdown, konservitaj konversacioj, serĉo, lokaj dokumentoj kaj MCP-iloj kun aprobo ĉe ĉiu alvoko). La panelo Resursoj montras procesoron, memoron, grafikkarton kaj malfermitajn konektojn. Windows, macOS, Linux; interfaco en 8 lingvoj; permesilo Apache-2.0.","tags":["loka AI","labortablo"]},"CartaColibri":{"line":"Loka AI-biblioteko sur la motoro Colibrì: ĝi indeksas la dosierujojn, kiujn vi elektas, serĉas en ili tuj kaj petas lokan modelon resumi, ĉerpi datumojn aŭ sintezi, ĉiam citante la fontan dosieron. Nenio forlasas vian komputilon.","detail":"Programo skribita en Rust, kun loka paĝo (127.0.0.1) kaj komandlinio. Ĝi indeksas la dosierujojn, kiujn vi elektas (originaloj estas nur legataj, neniam ŝanĝataj), serĉas plentekste (vortoj, “frazoj”, prefikso*, AND/OR/NOT, filtriloj laŭ tipo, grandeco, loko) kaj grupigas dosierojn. Loka modelo Colibrì resumas, ĉerpas (tabelo aŭ JSON, “NE TROVITA” anstataŭ divenoj), sintezas aŭ komparas, ĉiam kun citataj fontoj [S1], [S2] kaj poentaro de fundamento. Ĝi havas ankaŭ la malgrandan retumilon web-grab, nurlegan MCP-servilon, importojn (legosignoj, Obsidian, Zotero, RSS) kaj kontrolon de via propra teksto kontraŭ la biblioteko. Sen konto, sen telemetrio; interfaco en 8 lingvoj; alfa-versio 0.2; permesilo MIT.","tags":["loka AI","biblioteko"]},"PolyTabletop":{"line":"240 tabulaj ludoj, kiujn vi povas ludi kontraŭ la komputilo, en la terminalo aŭ en grafika fenestro, plus dupersona ludo ĉe unu klavaro aŭ tra la reto. Skribita en Rust; la motoro kaj la ludoj ne havas eksterajn dependecojn.","detail":"Clean-room kolekto de tabulaj ludoj skribita en Rust: 240 ludeblaj ludoj kontraŭ la komputilo, en la terminalo aŭ en grafika fenestro, plus hot-seat kaj reta dupersona ludo. Abstraktaj klasikaĵoj, kartaj kaj ludkubaj ludoj, originalaj variantoj de modernaj mekanikoj sub propraj nomoj, kunlaboraj ludoj kun AI-kunludanto, ludoj kun kaŝitaj roloj, festaj kaj vortaj ludoj; la katalogo havas 1200 enskribojn, kun ilaro por rolludoj (ludkuboj, folioj, generilo de karceroj, batala simulilo). AI-kontraŭulo (alfa-beta, MCTS), arenao AI-kontraŭ-AI, transskriboj kaj reludoj. Interfaco en 8 lingvoj; versio 0.9; permesilo MIT aŭ Apache-2.0.","tags":["tabulaj ludoj","Rust"]},"STRAJA":{"line":"Ŝildo kontraŭ AI-agentoj, kiuj legas vian telefonon: ĝi montras kiuj aplikaĵoj povas legi viajn sciigojn, ekranon, fotojn kaj SMS, avertas vin kiam nova ricevas aliron kaj kondukas vin al la agorda ekrano, kie vi revokas ĝin. Sen konto, sen permeso INTERNET.","detail":"Aplikaĵo por Android (APK) kaj iPhone (nesubskribita IPA). En Android ĝi listigas la aplikaĵojn kun aliro al sciigoj, alireblecaj servoj, la rolo de asistanto kaj permesoj de amaskomunikiloj kaj SMS, kun risk-poentaro por aplikaĵo kaj por la tuta telefono; perioda monitoro komparas la telefonon kun bazlinio kaj sciigas vin pri ĉiu nova aliro. Ĝi malfermas la precizan sistemagordan paĝon por revoki aliron kaj neniam ŝanĝas ion silente. Provizora aliro kun memorigilo, kaj gvidilo de 12 protektaj punktoj. En iPhone ne ekzistas kontrolo (iOS kaŝas permesojn de aliaj aplikaĵoj), nur la gvidilo, mana registro kaj memorigiloj. Ĝi ne povas haltigi agenton. Sen permeso INTERNET, sen sekurkopio; 8 lingvoj; versio 1.0; permesilo MIT.","tags":["privateco","telefono"]},"CUPLAJ":{"line":"Telefonio kun komuna linio por mergebla teatro: aro de ordinaraj Android-telefonoj fariĝas privata telefona centralo super la Wi-Fi de la loko, sen nubo, sen kontoj, sen reklamoj. Ĝia signa funkcio estas la “cuplaj”: la komuna linio de fiksaj telefonoj de la 1980-aj jaroj ĝis ĉirkaŭ 2006.","detail":"Android-aplikaĵo (APK) kaj aplikaĵo por iPhone/iPad (nesubskribita IPA). Organizantoj kaj aktoroj parolas kun spektantoj super la loka Wi-Fi; unu telefono (la kontrolo) estas la centralo. Ses telefonaj epokoj (1985 ciferdiska, 1995 klavara, 2003 poŝtelefono, 2025 saĝtelefono, 2045 portebla, 2080 komuna menso), la komuna linio, kie du abonantoj dividas unu linion, realaj vokoj, premparola anonco, scenejo-malantaŭa kanalo, signaloj (plenekrana teksto, vibro, sonorilo, fulmo, parolata voĉo, fantoma voko) kaj skripto kun GO kaj PLAY. Sen infrastrukturo, laŭvola reta ŝlosilo AES-128-GCM, rektaj P2P-vokoj. Sen analizo, sen serviloj, sen kontoj. 8 lingvoj; versio 1.10; permesilo MIT.","tags":["mergebla teatro","telefonio"]},"LUSTRUM":{"line":"Rehavu vian telefonon: ĝi trovas rubaĵon, duoblaĵojn, similajn fotojn kaj restaĵojn de aplikaĵoj, kaj forigas ilin nur kun via aprobo. Ĝi ne havas permeson INTERNET, do ĝi fizike ne povas sendi ion ien.","detail":"Android-aplikaĵo (Kotlin). Stokado laŭ dosiertipo, grandaj, malnovaj kaj rubaj dosieroj, precizaj duoblaĵoj (grandeco, rapida fingrospuro, poste SHA-256), similaj fotoj (perceptaj haŝoj), restaĵoj de malinstalitaj aplikaĵoj, JPEG-kunpremo, kaŝmemoroj, malklaraj kaj malhelaj fotoj, Swiper (maldekstre = forigi, dekstre = teni), planita purigado kaj 30-taga rubujo de LUSTRUM por malfari. Sen permeso INTERNET: nenio forlasas la telefonon. Sen magio je radika nivelo: Android 11+ tenas ĉiun ordinaran aplikaĵon ekster datumdosierujoj de aliaj aplikaĵoj. 8 lingvoj (maŝinaj tradukoj); beta-versio 0.8; permesilo MIT.","tags":["telefona purigilo","Android"]},"STENOGRAMA":{"line":"Transskribo de longa sono rekte en la retumilo, per loka Whisper: unu HTML-dosiero, sen konto, sen servilo, sen akvomarko. Via sona dosiero neniam forlasas la aparaton; nur la modelo Whisper estas elŝutata, unufoje.","detail":"Legas MP3 kaj WAV pecon post peco (do longo ne estas limigita de memoro); aliaj formatoj (M4A, OGG/Opus, MP4, FLAC) estas malkodataj tute. Ĉiu tranĉaĵo estas tranĉita ĉe paŭzo por ke vortoj ne estu dividitaj; progreso estas konservata, do vi povas halti kaj daŭrigi. Redaktilo en la paĝo (klaku tempon por aŭdi la lokon), forigo de tipaj fantomaj frazoj de Whisper, eksporto al .txt, .srt, .vtt, .docx aŭ la tondujo. Uzas WebGPU kiam disponebla, alie la procesoron (WASM). Instalebla PWA; la modelo restas en kaŝmemoro post la unua elŝuto. La biblioteko estas ŝargata de jsDelivr ĉe la unua transskribo, kontrolita per SHA-384. Interfaco en 7 lingvoj; permesilo MIT.","tags":["transskribo","sono"]},"GERMEN":{"line":"Trejnu malgrandan lingvan modelon de nulo, en pura Rust, per ordinara CPU: sen Python, sen CUDA, sen konto, sen reta aliro, sen telemetrio. Unu binaro, unu teksta dosiero, unu komando.","detail":"Rust-programo (sur Burn, kun ĝia pura-Rust CPU-fonaĵo), kiu trejnas GPT-stilan reton super bajtoj aŭ super BPE-vortprovizo lernita el via propra teksto, poste generas tekston el la trejnita modelo. GERMEN Studio: loka fenestro (127.0.0.1) kun la perda kurbo, la rapido kaj tekstaj specimenoj, en 8 lingvoj. Komandoj por mezuri la rapidon de via komputilo kaj por kontroli kaj ripari modeldosierojn. Ĝi estas laborejo por lerni kaj eksperimenti, ne fabriko de babilrobotoj: modelo de 1–25 milionoj da parametroj lernas la formon de teksto, ne mondscion. Sen GPU, sen miksita precizeco. Versio 0.6; permesilo MIT.","tags":["loka AI","Rust"]},"CUANTOR":{"line":"Simulilo de kvantuma komputilo por via labortablo, de 5 ĝis 1000 kubitoj, kun interfaco laŭ IBM Quantum Composer. Preciza matematiko, sed ne reala kvantuma aparataro.","detail":"Rust-programo en kvar partoj (kerno, fenestro, komandlinio, IBM-ligo) por Windows, macOS kaj Linux. Desegna tabulo kiel Composer de IBM: metu kolorajn pordojn sur liniojn (kubitoj) kaj rigardu stangojn kaj sferon montri la rezulton, dum teksta panelo skribas la saman cirkviton viva en OpenQASM kaj Qiskit. Tri kalkuliloj: unu kiu memoras ĉiun nombron (ĝis 28 kubitoj), unu tre rapida por simplaj pordoj (ĝis 4096) kaj unu por cirkvitoj kun malmultaj branĉoj. Mezuri, restarigi kaj if meze de rulo, viaj propraj pordoj, simulita bruo, rezultoj ripeteblaj per semo. Ĝi legas OpenQASM 2.0 kaj 3.0; vi povas malfermi la cirkviton en IBM Composer aŭ sendi ĝin al reala maŝino de IBM per via propra konta ŝlosilo (ne kontrolita sur reala aparataro de IBM). Interfaco en 8 lingvoj; versio 0.2.","tags":["kvantuma komputilo","simulilo"]},"ERATA":{"line":"Retumila korektilo, kiu kontrolas literumon, gramatikon, interpunkcion kaj tipografion rekte en via komputilo: sen konto, sen servilo, sen telemetrio. Plej profunda por la rumana.","detail":"Etendaĵo por Chromium kaj Firefox (Safari-versio netestita), skribita de nulo sen kodo, reguloj aŭ datumoj de LanguageTool aŭ alia kontrolilo. Ĝi funkcias en kampoj textarea, input kaj contenteditable kaj desegnas siajn substrekojn sen ŝanĝi la paĝon. Ĝi detektas la lingvon laŭ alineo, restarigas diakritajn signojn (ro, fr, es, pt) nur kie la korekto estas senduba, kaj havas profundajn rumanajn regulojn (komo-malsupre ș/ț, “să/sa”, “într-un”, la komo antaŭ “dar/însă”). Persona vortaro, propraj reguloj, ŝaltilo laŭ retejo, importo de vortaroj Hunspell. Laŭvola reverkado per loka modelo (nur localhost, implicite malŝaltita). Interfaco en 25 lingvoj. Versio 0.4; permesilo MIT.","tags":["korektilo","etendaĵo"]}});
